import React, { useEffect, useState } from "react";
import { createClient } from "@supabase/supabase-js";
import {
  Card,
  CardMedia,
  CardActionArea,
  Typography,
  Box,
  Dialog,
  DialogContent,
  IconButton,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import HTMLRenderer from "./HtmlRenderer";

const supabase = createClient(
  process.env.REACT_APP_SUPABASE_URL,
  process.env.REACT_APP_SUPABASE_ANON_KEY
);

function CardGrid({ news = [], setSelected}) {
  {/* 카드 그리드 */}
  return (
    <div className="grid w-full gap-4 grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 3xl:grid-cols-6">
      {news.map((item) => (
        <div key={item.id} className="w-full aspect-[2/3]">
          <Card
            sx={{
              width: "100%",
              height: "100%",
              borderRadius: "0.5rem",
              boxShadow: "rgba(0,0,0,0.1) 0px 3px 6px",
              transition: "transform 0.25s ease",
              display: "flex",
              flexDirection: "column",
              "&:hover": { transform: "translateY(-5px)" },
            }}
          >
            <CardActionArea
              sx={{ height: "100%", display: "flex", flexDirection: "column" }}
              onClick={() => setSelected(item)}
            >
              <Box sx={{ width: "100%", aspectRatio: "1 / 1", overflow: "hidden" }}>
                <CardMedia
                  component="img"
                  image={item.cover_image_url}
                  alt={item.title}
                  sx={{
                    width: "100%",
                    height: "100%",
                    objectFit: "contain", 
                    borderBottom: "1px solid rgba(0,0,0,0.08)",
                  }}
                />
              </Box>
              <Box sx={{ p: 1.2, width: "100%" }}>
                <Typography
                  variant="body2"
                  fontWeight="600"
                  sx={{
                    fontSize: "0.8rem",
                    lineHeight: 1.2,
                    overflow: "hidden",
                    display: "-webkit-box",
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: "vertical",
                  }}
                >
                  <HTMLRenderer htmlString={item.title} />
                </Typography>
                <Typography variant="caption" color="text.secondary" sx={{ fontSize: "0.7rem" }}>
                  {item.date}
                </Typography>
              </Box>
            </CardActionArea>
          </Card>
        </div>
      ))}
    </div>
  );
}

function NewsContainers() {
  const [pr, setPr] = useState([]);
  const [blog, setBlog] = useState([]);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    getNews();
  }, []);

  async function getNews() {
    const { data, error } = await supabase
      .from("news")
      .select("*")
      .order("date", { ascending: false });

    if (!error) {
      setBlog(data.filter((item) => item.type === "blog"));
      setPr(data.filter((item) => item.type === "pr"));
    }
  }
  return (
    <div className="flex flex-col items-center max-w-[70rem] w-full font-pretendard sm:px-0 px-5">
      <div className="flex flex-col items-start w-full mt-5">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Press Release</h2>
        <div className="w-full h-[1px] bg-gray-300 mb-8"></div>
        <CardGrid news={pr} setSelected={setSelected}/>
        <h2 className="text-2xl font-bold text-gray-800 mt-10 mb-2">Company Updates</h2>
        <div className="w-full h-[1px] bg-gray-300 mb-8"></div>
        <CardGrid news={blog} setSelected={setSelected}/>
      </div>

      {/* 상세보기 Dialog */}
      <Dialog
        open={!!selected}
        onClose={() => setSelected(null)}
        maxWidth="md"
        fullWidth
        scroll="paper"
      >
        {selected && (
          <DialogContent sx={{ position: "relative", p: 4 }}>
            <IconButton
              onClick={() => setSelected(null)}
              sx={{
                position: "absolute",
                top: 16,
                right: 16,
                background: "rgba(255,255,255,0.8)",
                "&:hover": { background: "white" },
              }}
            >
              <CloseIcon />
            </IconButton>

            {selected.cover_image_url && (
              <img
                src={selected.cover_image_url}
                alt=""
                className="object-contain rounded-lg mb-6 md:h-[300px] h-auto max-h-[300px] mx-auto"
              />
            )}

            <div className="h-px bg-gray-300 w-full border-gray-500 mb-10"/>

            <Typography variant="h5" fontWeight="bold" gutterBottom>
              <HTMLRenderer htmlString={selected.title} />
            </Typography>

            <Typography variant="subtitle2" color="text.secondary" mb={3}>
              {selected.date}
            </Typography>

            <div className="text-lg leading-8 font-[300] text-gray-700">
              <HTMLRenderer htmlString={selected.html} />
            </div>
          </DialogContent>
        )}
      </Dialog>
    </div>
  );
}

export default NewsContainers;
