function ProductPage() {
  const { link } = useParams();
  const navigate = useNavigate();

  let product = link? productList.find((item) => item.link === link) : null;

  useEffect(() => {
    if (!product && productList.length > 0) {
      navigate(`/product/gallery/${productList[0].link}`, { replace: true });
    }
  }, [product, productList, navigate]);

  if (!product) return null;

  return (
    <>
      <div
        className="w-full flex-grow overflow-y-scroll overflow-x-hidden"
        style={{ scrollSnapType: "y proximity" }}
      >
        <Banner
          title={getLocalizedValue("Our Products", "제품 목록")}
          src={require("../assets/banner/product-banner.jpg")}
        />
        <div className="w-full 
        px-10
        max-w-full md:max-w-[500px] xl:max-w-[700px] 3xl:max-w-[900px] 
        text-sm xl:text-base
        mb-5 m-auto grid grid-cols-2 overflow-hidden text-white ">
          {productList.map((p) =>
            p.name === product.name ? (
              <div
                key={p.name}
                className="px-3 py-2 bg-brand-kool-blue text-center text-white font-bold flex items-center justify-center border-2 border-brand-kool-blue"
              >
                {p.name}
              </div>
            ) : (
              <Link
                key={p.name}
                className="flex items-center px-3 py-1 cursor-pointer text-center justify-center bg-white text-brand-steel-grey border-2 border-brand-kool-blue
                font-normal
                hover:bg-brand-electric-blue hover:text-white
                hover:border-brand-electric-blue hover:font-bold
                duration-200 ease-in-out transition-all"
                to={`/product/gallery/${p.link}`}
              >
                {p.name}
              </Link>
            )
          )}
        </div>

        <main className="flex justify-center items-center">
          <Products product={product} />
        </main>
        <ContactFooter />
      </div>
    </>
  );
}



export default ProductPage;
